package kestra_api_client

import "time"

// Hand-written models for the Cases and Case Templates APIs (kestra-ee
// CasesController / CaseTemplatesController). These mirror the backend's
// Api* response records and *Request bodies; unlike the model_*.go files
// generated by the OpenAPI generator, this file is maintained by hand.

// ---- shared subject types ----

// CaseSubjectRef is a resolved user or group reference (id + display label).
// The optional Type ("USER"/"GROUP") is present on case assignees but omitted
// on case-template subjects.
type CaseSubjectRef struct {
	Id    string `json:"id"`
	Label string `json:"label"`
	Type  string `json:"type,omitempty"`
}

// CaseSubjects groups resolved user and group references, as returned on a case
// or case template.
type CaseSubjects struct {
	Users  []CaseSubjectRef `json:"users"`
	Groups []CaseSubjectRef `json:"groups"`
}

// CaseSubjectsInput is the request-side counterpart of CaseSubjects: plain lists
// of user and group ids to assign or watch.
type CaseSubjectsInput struct {
	Users  []string `json:"users,omitempty"`
	Groups []string `json:"groups,omitempty"`
}

// CaseAction is a flow attached to a case as a runnable action.
type CaseAction struct {
	Label     string `json:"label,omitempty"`
	Namespace string `json:"namespace"`
	FlowId    string `json:"flowId"`
}

// ---- response types ----

// Case mirrors CasesController.ApiCase. Deeply nested or free-form fields (sla,
// resolution, customFields, autoAttach, origin) are left as generic values since
// they are not the focus of SDK consumers.
type Case struct {
	Id                 string        `json:"id"`
	TenantId           string        `json:"tenantId,omitempty"`
	Namespace          string        `json:"namespace,omitempty"`
	Title              string        `json:"title,omitempty"`
	Description        string        `json:"description,omitempty"`
	Severity           string        `json:"severity,omitempty"`
	Status             string        `json:"status,omitempty"`
	Assignees          *CaseSubjects `json:"assignees,omitempty"`
	Watchers           *CaseSubjects `json:"watchers,omitempty"`
	CustomFields       []interface{} `json:"customFields,omitempty"`
	Sla                interface{}   `json:"sla,omitempty"`
	AcknowledgementSla interface{}   `json:"acknowledgementSla,omitempty"`
	ResolutionSla      interface{}   `json:"resolutionSla,omitempty"`
	Created            *time.Time    `json:"created,omitempty"`
	Updated            *time.Time    `json:"updated,omitempty"`
	AcknowledgedAt     *time.Time    `json:"acknowledgedAt,omitempty"`
	ResolvedAt         *time.Time    `json:"resolvedAt,omitempty"`
	Resolution         interface{}   `json:"resolution,omitempty"`
	ResolvedBy         string        `json:"resolvedBy,omitempty"`
	ResolvedByName     string        `json:"resolvedByName,omitempty"`
	Actions            []CaseAction  `json:"actions,omitempty"`
	AssetIds           []string      `json:"assetIds,omitempty"`
	CreatedBy          string        `json:"createdBy,omitempty"`
	Origin             interface{}   `json:"origin,omitempty"`
	TemplateId         string        `json:"templateId,omitempty"`
	AutoAttach         []interface{} `json:"autoAttach,omitempty"`
	Deleted            bool          `json:"deleted"`
}

// CaseEvent mirrors CasesController.ApiCaseEvent (a comment or lifecycle event).
type CaseEvent struct {
	Id          string                 `json:"id"`
	CaseId      string                 `json:"caseId,omitempty"`
	Type        string                 `json:"type,omitempty"`
	AuthorId    string                 `json:"authorId,omitempty"`
	AuthorName  string                 `json:"authorName,omitempty"`
	Body        string                 `json:"body,omitempty"`
	Payload     map[string]interface{} `json:"payload,omitempty"`
	Attachments []interface{}          `json:"attachments,omitempty"`
	Created     *time.Time             `json:"created,omitempty"`
}

// CaseExecution mirrors CasesController.ApiCaseExecution (a linked execution,
// hydrated with live state).
type CaseExecution struct {
	ExecutionId string     `json:"executionId"`
	Namespace   string     `json:"namespace,omitempty"`
	FlowId      string     `json:"flowId,omitempty"`
	State       string     `json:"state,omitempty"`
	Auto        bool       `json:"auto"`
	Created     *time.Time `json:"created,omitempty"`
	Found       bool       `json:"found"`
}

// CaseSummary mirrors CasesController.ApiCaseSummary (a lightweight case card).
type CaseSummary struct {
	Id        string        `json:"id"`
	Title     string        `json:"title,omitempty"`
	Severity  string        `json:"severity,omitempty"`
	Status    string        `json:"status,omitempty"`
	Updated   *time.Time    `json:"updated,omitempty"`
	Assignees *CaseSubjects `json:"assignees,omitempty"`
}

// CaseAsset mirrors CasesController.ApiCaseAsset. Origin is "EXPLICIT" or
// "DERIVED".
type CaseAsset struct {
	AssetId string `json:"assetId"`
	Origin  string `json:"origin,omitempty"`
}

// CaseTemplate mirrors CaseTemplatesController.ApiCaseTemplate.
type CaseTemplate struct {
	Id                    string        `json:"id"`
	TenantId              string        `json:"tenantId,omitempty"`
	Name                  string        `json:"name,omitempty"`
	Namespace             string        `json:"namespace,omitempty"`
	DefaultSeverity       string        `json:"defaultSeverity,omitempty"`
	DefaultAssignees      *CaseSubjects `json:"defaultAssignees,omitempty"`
	DefaultWatchers       *CaseSubjects `json:"defaultWatchers,omitempty"`
	TitlePattern          string        `json:"titlePattern,omitempty"`
	Description           string        `json:"description,omitempty"`
	Sla                   interface{}   `json:"sla,omitempty"`
	ResolutionReasons     []string      `json:"resolutionReasons,omitempty"`
	RequireResolutionNote bool          `json:"requireResolutionNote"`
	CustomFields          []interface{} `json:"customFields,omitempty"`
	DefaultActions        []CaseAction  `json:"defaultActions,omitempty"`
	IsDefault             bool          `json:"isDefault"`
	CreatedBy             string        `json:"createdBy,omitempty"`
	Created               *time.Time    `json:"created,omitempty"`
	Updated               *time.Time    `json:"updated,omitempty"`
	Deleted               bool          `json:"deleted"`
}

// ---- paged wrappers (mirror PagedResults<T>: results + total) ----

type PagedResultsCase struct {
	Results []Case `json:"results"`
	Total   int64  `json:"total"`
}

type PagedResultsCaseEvent struct {
	Results []CaseEvent `json:"results"`
	Total   int64       `json:"total"`
}

type PagedResultsCaseExecution struct {
	Results []CaseExecution `json:"results"`
	Total   int64           `json:"total"`
}

type PagedResultsCaseSummary struct {
	Results []CaseSummary `json:"results"`
	Total   int64         `json:"total"`
}

type PagedResultsCaseAsset struct {
	Results []CaseAsset `json:"results"`
	Total   int64       `json:"total"`
}

type PagedResultsCaseSubjectRef struct {
	Results []CaseSubjectRef `json:"results"`
	Total   int64            `json:"total"`
}

type PagedResultsCaseTemplate struct {
	Results []CaseTemplate `json:"results"`
	Total   int64          `json:"total"`
}

// ---- request bodies ----

// CaseCreateRequest mirrors CasesController.CaseCreateRequest.
type CaseCreateRequest struct {
	Namespace    string             `json:"namespace"`
	Title        string             `json:"title"`
	Description  string             `json:"description,omitempty"`
	Severity     string             `json:"severity,omitempty"`
	Status       string             `json:"status,omitempty"`
	TemplateId   string             `json:"templateId,omitempty"`
	Sla          interface{}        `json:"sla,omitempty"`
	Assignees    *CaseSubjectsInput `json:"assignees,omitempty"`
	Watchers     *CaseSubjectsInput `json:"watchers,omitempty"`
	CustomFields []interface{}      `json:"customFields,omitempty"`
	Actions      []CaseAction       `json:"actions,omitempty"`
}

// CaseUpdateRequest mirrors CasesController.CaseUpdateRequest.
type CaseUpdateRequest struct {
	Namespace    string        `json:"namespace,omitempty"`
	Title        string        `json:"title,omitempty"`
	Description  string        `json:"description,omitempty"`
	Severity     string        `json:"severity,omitempty"`
	CustomFields []interface{} `json:"customFields,omitempty"`
}

// CaseResolveRequest mirrors CasesController.ResolveRequest.
type CaseResolveRequest struct {
	Reason string `json:"reason"`
	Note   string `json:"note,omitempty"`
}

// CaseCancelRequest mirrors CasesController.CancelRequest.
type CaseCancelRequest struct {
	Reason string `json:"reason,omitempty"`
	Note   string `json:"note,omitempty"`
}

// CaseStatusRequest mirrors CasesController.StatusRequest.
type CaseStatusRequest struct {
	Status     string      `json:"status"`
	Resolution interface{} `json:"resolution,omitempty"`
}

// CaseAssignRequest mirrors CasesController.AssignRequest.
type CaseAssignRequest struct {
	Assignees *CaseSubjectsInput `json:"assignees,omitempty"`
	Watchers  *CaseSubjectsInput `json:"watchers,omitempty"`
	Note      string             `json:"note,omitempty"`
}

// CaseAutoAttachRequest mirrors CasesController.AutoAttachRequest. States are
// execution State.Type names, e.g. "SUCCESS", "FAILED".
type CaseAutoAttachRequest struct {
	Namespace string   `json:"namespace"`
	FlowId    string   `json:"flowId"`
	States    []string `json:"states"`
}

// CaseLinkExecutionsRequest mirrors CasesController.LinkExecutionsRequest.
type CaseLinkExecutionsRequest struct {
	ExecutionIds []string `json:"executionIds"`
}

// CaseLinkExecutionsByQueryRequest mirrors CasesController.LinkExecutionsByQueryRequest.
type CaseLinkExecutionsByQueryRequest struct {
	Filters []QueryFilter `json:"filters"`
}

// CaseFromExecutionsRequest mirrors CasesController.FromExecutionsRequest. The
// case payload is serialized under the JSON key "case".
type CaseFromExecutionsRequest struct {
	Case         *CaseCreateRequest `json:"case"`
	ExecutionIds []string           `json:"executionIds"`
}

// CaseFromExecutionsByQueryRequest mirrors CasesController.FromExecutionsByQueryRequest.
type CaseFromExecutionsByQueryRequest struct {
	Case    *CaseCreateRequest `json:"case"`
	Filters []QueryFilter      `json:"filters"`
}

// CaseAttachAssetRequest mirrors CasesController.AttachAssetRequest.
type CaseAttachAssetRequest struct {
	AssetId string `json:"assetId"`
}

// CaseAttachActionRequest mirrors CasesController.AttachActionRequest.
type CaseAttachActionRequest struct {
	Label     string `json:"label"`
	Namespace string `json:"namespace"`
	FlowId    string `json:"flowId"`
}

// CaseRunActionRequest mirrors CasesController.RunActionRequest.
type CaseRunActionRequest struct {
	Namespace    string                 `json:"namespace"`
	FlowId       string                 `json:"flowId"`
	Inputs       map[string]interface{} `json:"inputs,omitempty"`
	Labels       []Label                `json:"labels,omitempty"`
	ScheduleDate *time.Time             `json:"scheduleDate,omitempty"`
	Breakpoints  []string               `json:"breakpoints,omitempty"`
}

// CaseTemplateRequest mirrors CaseTemplatesController.CaseTemplateRequest.
type CaseTemplateRequest struct {
	Name                  string             `json:"name"`
	Namespace             string             `json:"namespace,omitempty"`
	DefaultSeverity       string             `json:"defaultSeverity,omitempty"`
	DefaultAssignees      *CaseSubjectsInput `json:"defaultAssignees,omitempty"`
	DefaultWatchers       *CaseSubjectsInput `json:"defaultWatchers,omitempty"`
	TitlePattern          string             `json:"titlePattern,omitempty"`
	Description           string             `json:"description,omitempty"`
	Sla                   interface{}        `json:"sla,omitempty"`
	ResolutionReasons     []string           `json:"resolutionReasons,omitempty"`
	RequireResolutionNote bool               `json:"requireResolutionNote"`
	CustomFields          []interface{}      `json:"customFields,omitempty"`
	DefaultActions        []CaseAction       `json:"defaultActions,omitempty"`
	IsDefault             bool               `json:"isDefault"`
}
